def transform(grid):
    """Extend each solid 3x3 color block through its center row and column."""
    h, w = len(grid), len(grid[0])
    blocks = []
    for r in range(h - 2):
        for c in range(w - 2):
            color = grid[r][c]
            if color and all(grid[rr][cc] == color
                             for rr in range(r, r + 3)
                             for cc in range(c, c + 3)):
                blocks.append((r + 1, c + 1, color))
    out = [row[:] for row in grid]
    horizontal = {}
    vertical = {}
    for r, c, color in blocks:
        horizontal[r] = color
        vertical[c] = color
    for r, color in horizontal.items():
        out[r] = [color] * w
    for c, color in vertical.items():
        for r in range(h):
            out[r][c] = color
    for r in horizontal:
        for c in vertical:
            if horizontal[r] != vertical[c]:
                out[r][c] = 0
    return out
